```javascript
import { gsap } from 'gsap';
import { Group, Mesh, Cylinder, Sphere, PlaneGeometry, Scene } from 'three/webgpu';
import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { color, uniform, float, vec3, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const resources = {
    cleanup() {
      if (this.orbitResult) this.orbitResult.cleanup();
      gsap.killTweensOf(group.rotation);
      gsap.killTweensOf(group.position);
    },
    orbitResult: null,
  };

  group.userData.cleanup = () => resources.cleanup();
  group.userData.handlers = {};

  // Parse colors from config
  const colors = config.intent?.visualSpec?.colors || {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  const gradientStops = config.intent?.visualSpec?.colors?.gradientStops || [
    { at: 0, hex: '#0b0b10' },
    { at: 0.65, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];

  // ===== BACKDROP PLANE WITH GRADIENT =====
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    colorNode: mix(
      color(gradientStops[0].hex),
      color(gradientStops[2].hex),
      mix(
        color(gradientStops[0].hex),
        color(gradientStops[1].hex),
        float(0.65)
      )
    ),
    emissiveIntensity: 0,
    metalness: 0,
    roughness: 1,
    side: ctx.THREE.BackSide,
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -3;
  group.add(backdrop);

  // ===== CONTACT SHADOW PLANE =====
  const shadowGeo = new PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshStandardNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
    emissiveIntensity: 0,
    metalness: 0,
    roughness: 1,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -1.2, -0.05);
  shadow.rotation.x = -Math.PI / 2;
  group.add(shadow);

  // ===== LOAD PRIMARY GEAR MESH =====
  let primaryGear = null;
  let secondaryGear = null;
  let gearGroup = new Group();
  group.add(gearGroup);

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    primaryGear = gltf.scene.clone();

    // Scale primary gear to 1.6 diameter
    primaryGear.scale.set(1.6, 1.6, 1.6);
    primaryGear.position.set(0, 0, 0);
    primaryGear.rotation.set(0, 0, 0);

    // Apply PBR material to primary gear
    primaryGear.traverse((child) => {
      if (child.isMesh) {
        const newMat = new MeshStandardNodeMaterial({
          roughness: 0.5,
          metalness: 0.55,
          clearcoat: 0.2,
          clearcoatRoughness: 0.3,
        });

        // Copy map if it exists
        if (child.material?.map) {
          newMat.map = child.material.map;
          newMat.mapNode = undefined;
        }

        newMat.color.setHex(0xb0b0b0);
        child.material = newMat;
      }
    });

    gearGroup.add(primaryGear);

    // ===== SECONDARY GEAR INSTANCE =====
    secondaryGear = primaryGear.clone();
    secondaryGear.scale.set(0.9, 0.9, 0.9);
    secondaryGear.position.set(1.15, 0.35, -0.1);

    gearGroup.add(secondaryGear);

    // ===== JEWEL PIVOT (primary hub) =====
    const jewelGeo = new Sphere(0.12);
    const jewelMat = new MeshPhysicalNodeMaterial({
      color: color(colors.accent),
      transmission: 0.6,
      ior: 1.76,
      emissive: color(colors.accent),
      emissiveIntensity: 1.8,
      roughness: 0.1,
      metalness: 0,
      side: ctx.THREE.FrontSide,
    });
    const jewel = new Mesh(jewelGeo, jewelMat);
    jewel.position.set(0, 0, 0);
    gearGroup.add(jewel);

    // ===== ARBOR SHAFTS =====
    const arbor1Geo = new Cylinder(0.05, 0.05, 0.8, 16);
    const arborMat = new MeshStandardNodeMaterial({
      color: colors.ink,
      metalness: 0.3,
      roughness: 0.4,
    });
    const arbor1 = new Mesh(arbor1Geo, arborMat);
    arbor1.position.set(0, 0, 0);
    gearGroup.add(arbor1);

    const arbor2 = new Mesh(arbor1Geo, arborMat.clone());
    arbor2.position.set(1.15, 0.35, -0.1);
    gearGroup.add(arbor2);
  });

  // ===== TEXT CONTENT =====
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Headline: "The going train"
  const headlineItem = items.find((i) => i.role === 'headline') || {
    text: 'The going train',
    role: 'headline',
    typography: { fontSize: 68, fontWeight: 600 },
  };
  const headlineText = ctx.fontAtlas.createText(headlineItem.text || 'The going train', {
    fontSize: 68,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: -0.34,
  });
  headlineText.position.set(0, -1.7, 0.1);
  group.add(headlineText);

  // Caption: "34 COMPONENTS / HAND-FINISHED"
  const captionItem = items.find((i) => i.role === 'caption') || {
    text: '34 COMPONENTS / HAND-FINISHED',
    role: 'caption',
    typography: { fontSize: 18, fontWeight: 400 },
  };
  const captionText = ctx.fontAtlas.createText(captionItem.text || '34 COMPONENTS / HAND-FINISHED', {
    fontSize: 18,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 1.44,
  });
  captionText.position.set(0, -2.1, 0.1);
  group.add(captionText);

  // ===== CINEMATIC PRIMITIVES =====
  const cinematicPrimitives = config.cinematicPrimitives || [
    {
      name: 'orbit',
      trigger: 'time',
      params: { speed: 0.08, radius: 0.2 },
    },
  ];

  for (const primitive of cinematicPrimitives) {
    if (primitive.name === 'orbit' && primitive.trigger === 'time') {
      // Apply orbit primitive to gearGroup for camera-like drift effect on the scene
      const orbitResult = ctx.primitives['orbit'](gearGroup, {
        radius: primitive.params.radius || 0.2,
        period: (2 * Math.PI) / (primitive.params.speed || 0.08),
      });
      resources.orbitResult = orbitResult;
    }
  }

  // ===== GEAR ROTATION (synchronized meshing) =====
  // Primary: 0.08 rad/s, Secondary: -0.142 rad/s (16:9 ratio)
  const gearRotationTimeline = gsap.timeline({ repeat: -1 });

  if (primaryGear && secondaryGear) {
    gearRotationTimeline
      .to(
        primaryGear.rotation,
        {
          z: Math.PI * 2,
          duration: 2 * Math.PI / 0.08,
          ease: 'none',
        },
        0
      )
      .to(
        secondaryGear.rotation,
        {
          z: -Math.PI * 2,
          duration: 2 * Math.PI / 0.142,
          ease: 'none',
        },
        0
      );
  }

  // Wrap cleanup to include gear rotation timeline
  const originalCleanup = resources.cleanup.bind(resources);
  resources.cleanup = function () {
    originalCleanup();
    gearRotationTimeline.kill();
  };

  group.userData.cleanup = () => resources.cleanup();

  return group;
}
